def bfs(g, gray, bg, diag=False):
 n=len(g);m=len(g[0]); colors=set(x for r in g for x in r)-{gray,bg}
 own=[[None]*m for _ in range(n)]; state=[[0]*m for _ in range(n)] # 0 unvisited,1 owned,2 conflict
 q=deque()
 dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 for r in range(n):
  for c in range(m):
   if g[r][c]==gray:
    adj={g[rr][cc] for rr,cc in ((r+dr,c+dc) for dr,dc in dirs) if 0<=rr<n and 0<=cc<m and g[rr][cc] in colors}
    if len(adj)==1: own[r][c]=next(iter(adj));state[r][c]=1;q.append((r,c))
    elif adj: state[r][c]=2
 while q:
  layer=list(q);q.clear(); claims={}
  for r,c in layer:
   for dr,dc in dirs:
    rr,cc=r+dr,c+dc
    if 0<=rr<n and 0<=cc<m and g[rr][cc]==gray and state[rr][cc]==0:
     claims.setdefault((rr,cc),set()).add(own[r][c])
  for (r,c),cs in claims.items():
   if len(cs)==1: own[r][c]=next(iter(cs));state[r][c]=1;q.append((r,c))
   else: state[r][c]=2
 return [[own[r][c] if g[r][c]==gray and state[r][c]==1 else g[r][c] for c in range(m)] for r in range(n)]
