def segments(g,gray):
 n=len(g);m=len(g[0]); G={(r,c) for r in range(n) for c in range(m) if g[r][c]==gray}
 neigh={p:[(p[0]+dr,p[1]+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)] if (p[0]+dr,p[1]+dc) in G] for p in G}
 # junctions degree !=2 OR deg2 turn? keep turns as normal connecting but segment orientation changes. split turns as nodes
 nodes={p for p,ns in neigh.items() if len(ns)!=2 or (len(ns)==2 and (ns[0][0]!=ns[1][0]))}
 # includes endpoints, junctions, turns
 seen=set();segs=[]
 for node in nodes:
  for nb in neigh[node]:
   edge=tuple(sorted((node,nb)))
   if edge in seen:continue
   seg=[node];prev=node;cur=nb
   while True:
    seen.add(tuple(sorted((prev,cur))));seg.append(cur)
    if cur in nodes:break
    nxt=next(p for p in neigh[cur] if p!=prev);prev,cur=cur,nxt
   segs.append(seg)
 # any cycles
 return G,nodes,segs

def seg_transform(g,gray,bg):
 g=[r[:] for r in g];n=len(g);m=len(g[0]);G,nodes,segs=segments(g,gray)
 for seg in segs:
  # nodes degree>=3 stay gray. endpoints and turn nodes can be colored based segment.
  core=[p for p in seg if len([q for q in [(p[0]-1,p[1]),(p[0]+1,p[1]),(p[0],p[1]-1),(p[0],p[1]+1)] if q in G])<=2]
  if not core:continue
  # all non-bg colors adjacent perpendicular to any segment cell
  cols=[]
  for r,c in seg:
   for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
    rr,cc=r+dr,c+dc
    if 0<=rr<n and 0<=cc<m and (rr,cc) not in G and g[rr][cc]!=bg:cols.append(g[rr][cc])
  if cols:
   col=Counter(cols).most_common(1)[0][0]
   for r,c in core:g[r][c]=col
 return g
for k,p in enumerate(pairs):
 cnt=Counter(x for r in p['input'] for x in r);gray=cnt.most_common(2)[1][0];bg=cnt.most_common(1)[0][0]
